INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (689, 178, 2, 'input', 'text', 'inferred', 0, 0, NULL, 'any expression that returns text or container data to send to the model for conversion to embedding vectors.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (690, 179, 0, 'text', 'text', 'inferred', 0, 0, NULL, 'any text expression representing embedding vectors as a JSON array.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (691, 179, 1, 'fileNameWithExtension', 'text', 'inferred', 1, 0, NULL, 'any text expression representing the filename and extension to use for the returned container data. If not specified, a default filename and extension is used.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (692, 180, 0, 'data', 'text', 'inferred', 0, 0, NULL, 'any text expression that returns embedding vectors as container data, such as a reference to a container field.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (693, 181, 0, 'layoutName', 'text', 'inferred', 0, 0, NULL, 'a text expression representing the name of the layout. If layoutName is an empty string (""), the current layout is used.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (694, 182, 0, 'modelName', 'any', 'inferred', 0, 0, NULL, 'the name of the model to evaluate. This value must match the name of a previously loaded model.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (695, 183, 0, 'ragAccountName', 'text', 'inferred', 0, 0, NULL, 'a text expression for the name of the RAG account to use. In the current file, use the Configure RAG Account script step to set up the account and assign it this name any time before this function is used.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (696, 183, 1, 'spaceID', 'any', 'inferred', 1, 0, NULL, 'ID of a RAG space. If omitted, returns information about all RAG spaces for the specified account.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (697, 184, 0, 'tableOccurrenceNames', 'text', 'inferred', 0, 0, NULL, 'a text expression for a JSON array of the table occurrences to return.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (698, 184, 1, 'ignoreError', 'boolean', 'inferred', 0, 0, NULL, 'if set to True, returns DDL information for the table occurrences that cause no error. If False, returns DDL information when no table occurrences cause an error; otherwise returns "?" to indicate an error and logs the table occurrences that caused the error in the AI call log (see Set AI Call Logging script step).');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (699, 185, 0, 'text', 'text', 'inferred', 0, 0, NULL, 'any text expression.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (700, 186, 0, 'data', 'text', 'inferred', 0, 0, NULL, 'any text expression, text field, or container field that contains an embedding vector.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (701, 186, 1, 'dimension', 'number', 'inferred', 1, 0, NULL, 'the number of vector dimensions to use for normalization. If omitted, or if the value is greater than the vector''s actual dimension size or less than or equal to 0, the entire vector dimension size is used in the calculation.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (702, 187, 0, 'modelName', 'text', 'inferred', 0, 0, NULL, 'any text expression that specifies the name of a trained regression model that has been loaded into memory.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (703, 187, 1, 'v1', 'text', 'inferred', 0, 0, NULL, 'any text expression, field, or container field that contains the input features for prediction. Can be provided as a JSON array (for example, [1.2, 3.4, 5.6]) or as binary container data containing embedding vectors.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (704, 188, 0, 'v1', 'text', 'inferred', 0, 0, NULL, 'and v2 - any text expression, text field, or container field that contains embedding vectors with the same dimensions.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (705, 188, 1, 'v2', 'any', 'inferred', 0, 0, NULL, NULL);
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (706, 189, 0, 'filemakerPath', 'text', 'inferred', 0, 0, NULL, 'any text expression or text field containing a path in FileMaker format.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (707, 189, 1, 'format', 'number', 'inferred', 0, 0, NULL, 'a numeric value that specifies the standard format in which to return the path (see below).');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (708, 190, 0, 'standardPath', 'text', 'inferred', 0, 0, NULL, 'any text expression or text field containing a path in a standard format.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (709, 190, 1, 'format', 'number', 'inferred', 0, 0, NULL, 'a numeric value that specifies the standard format that standardPath is in (see below).');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (710, 191, 0, 'addonID', 'text', 'inferred', 0, 0, NULL, 'text that specifies the Universally Unique Identifier (UUID) of an installed or packaged add-on.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (711, 192, 0, 'field', 'text', 'inferred', 0, 0, NULL, 'any field object or evaluation of a text expression that refers to a field''s name');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (712, 193, 0, 'field', 'text', 'inferred', 0, 0, NULL, 'any field object or evaluation of a text expression that refers to a field''s name');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (713, 194, 0, 'objectName', 'any', 'inferred', 0, 0, NULL, 'the name of a named layout object on the current layout.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (714, 194, 1, 'attributeName', 'any', 'inferred', 0, 0, NULL, 'the name of a supported attribute (see below).');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (715, 194, 2, 'repetitionNumber', 'number', 'inferred', 1, 0, NULL, 'the repetition number (for repeating fields).');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (716, 194, 3, 'portalRowNumber', 'number', 'inferred', 1, 0, NULL, 'the number of the row in the portal.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (717, 195, 0, 'objectID', 'text', 'inferred', 0, 0, NULL, 'text that specifies the Universally Unique Identifier (UUID) or the owner ID of a layout object.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (718, 196, 0, 'name', 'text', 'inferred', 0, 0, NULL, 'a text expression that specifies the name of the persistent data entry.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (719, 196, 1, 'instanceID', 'text', 'inferred', 0, 0, NULL, 'a text expression that identifies the specific instance of the entry. Must match the instance ID used when storing the data. Can be an empty string ("").');
