INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (721, 197, 1, 'tableOccurrenceOrPortal', 'text', 'inferred', 1, 0, NULL, 'a text expression that specifies the name of a related table occurrence or the object name of a portal on the current layout.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (722, 199, 0, 'name', 'text', 'inferred', 0, 0, NULL, 'a text expression that specifies the name of an entry to search for.');
