INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (772, 230, 0, 'UUID', 'any', 'inferred', 0, 0, NULL, 'the universally unique identifier for iBeacons to search for. The UUID identifies one or more iBeacons as a specific type or from a specific organization. For example, iBeacons for all branches of a department store could share the same UUID.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (773, 230, 1, 'timeout', 'number', 'inferred', 1, 0, NULL, 'the number of seconds to wait before returning a value. If timeout is not specified, the function returns a value after five seconds.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (774, 230, 2, 'major', 'any', 'inferred', 1, 0, NULL, 'the value identifying a group of iBeacons. For example, all iBeacons in a specific branch of a department store could share the same major value.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (775, 230, 3, 'minor', 'any', 'inferred', 1, 0, NULL, 'the value identifying specific iBeacons within a group of iBeacons. For example, all iBeacons in the toys section of a specific branch of a department store could share the same minor value.');
INSERT INTO "function_parameters" ("id", "function_id", "position", "name", "type", "type_source", "optional", "repeatable", "group_key", "help_description") VALUES (899, 231, 0, 'name', 'any', 'curated', 0, 0, NULL, NULL);
